def icon(name, cls=""):
    inner = ICONS.get(name, ICONS["package"])
    return Markup(
        f'<svg class="icon {cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
        f'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{inner}</svg>'
    )
